/**
 * Expo config plugin: puts AuCourant's Java layer into the generated android/ project.
 *
 * android/ is generated by `expo prebuild` (Continuous Native Generation) and is not
 * committed. The Java sources live in native/android/java and this plugin, on every
 * prebuild:
 *   1. copies them into android/app/src/main/java,
 *   2. registers AuCourantPackage in MainApplication,
 *   3. adds the FileProvider used to share exported reports,
 *   4. builds for 64-bit ARM phones only (founder, 2026-11-21),
 *   5. adds Room (SQLite storage) with its Java annotation processor,
 *   6. declares SmsReceiver, which hears about new SMS,
 *   7. adds AndroidX Biometric (fingerprint unlock).
 */
const fs = require('fs')
const path = require('path')
const { withDangerousMod, withMainApplication, withAndroidManifest, withAppBuildGradle, withGradleProperties, AndroidConfig } = require('expo/config-plugins')

const PKG = 'com.aucourant.nativebridge'
const SRC = path.join('native', 'android', 'java')
const PATHS_XML = 'aucourant_file_paths'

function copyDir(from, to) {
  fs.mkdirSync(to, { recursive: true })
  for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
    const a = path.join(from, entry.name)
    const b = path.join(to, entry.name)
    if (entry.isDirectory()) copyDir(a, b)
    else fs.copyFileSync(a, b)
  }
}

const withJavaSources = (config) =>
  withDangerousMod(config, [
    'android',
    async (cfg) => {
      const root = cfg.modRequest.projectRoot
      const main = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'main')
      copyDir(path.join(root, SRC), path.join(main, 'java'))
      const xmlDir = path.join(main, 'res', 'xml')
      fs.mkdirSync(xmlDir, { recursive: true })
      fs.writeFileSync(
        path.join(xmlDir, `${PATHS_XML}.xml`),
        '<?xml version="1.0" encoding="utf-8"?>\n<paths>\n  <files-path name="exports" path="exports/" />\n</paths>\n',
      )
      return cfg
    },
  ])

const withPackageRegistered = (config) =>
  withMainApplication(config, (cfg) => {
    const src = cfg.modResults.contents
    const line = cfg.modResults.language === 'java' ? `packages.add(new ${PKG}.AuCourantPackage());` : `add(${PKG}.AuCourantPackage())`
    if (src.includes(`${PKG}.AuCourantPackage`)) return cfg
    const anchor = cfg.modResults.language === 'java' ? /(List<ReactPackage> packages = new PackageList\(this\)\.getPackages\(\);)/ : /(PackageList\(this\)\.packages\.apply \{)/
    if (!anchor.test(src)) {
      throw new Error('[with-aucourant-native] Could not find the package list in MainApplication. Update the anchor for this Expo SDK.')
    }
    cfg.modResults.contents = src.replace(anchor, `$1\n              ${line}`)
    return cfg
  })

const withFileProvider = (config) =>
  withAndroidManifest(config, (cfg) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults)
    app.provider = app.provider ?? []
    const name = 'androidx.core.content.FileProvider'
    if (!app.provider.some((p) => p.$['android:authorities']?.endsWith('.aucourant.files'))) {
      app.provider.push({
        $: {
          'android:name': name,
          'android:authorities': '${applicationId}.aucourant.files',
          'android:exported': 'false',
          'android:grantUriPermissions': 'true',
        },
        'meta-data': [{ $: { 'android:name': 'android.support.FILE_PROVIDER_PATHS', 'android:resource': `@xml/${PATHS_XML}` } }],
      })
    }
    return cfg
  })

/**
 * 64-bit only. Every 64-bit Android phone is arm64-v8a; 32-bit (armeabi-v7a, x86) is dropped.
 * x86_64 is left out too because only emulators use it: add it here to test on one.
 */
const ABIS = 'arm64-v8a'
const with64BitOnly = (config) =>
  withGradleProperties(config, (cfg) => {
    const props = cfg.modResults.filter((p) => !(p.type === 'property' && p.key === 'reactNativeArchitectures'))
    props.push({ type: 'property', key: 'reactNativeArchitectures', value: ABIS })
    cfg.modResults = props
    return cfg
  })

/** Room for app storage (docs/superpowers/specs/2026-11-21-room-storage-design.md). Java only: annotationProcessor, no KSP or kapt. */
const ROOM = '2.8.5'
const withRoom = (config) =>
  withAppBuildGradle(config, (cfg) => {
    const src = cfg.modResults.contents
    if (src.includes('androidx.room:room-runtime')) return cfg
    const anchor = /^dependencies \{\r?\n/m
    if (!anchor.test(src)) throw new Error('[with-aucourant-native] Could not find the dependencies block in app/build.gradle.')
    const lines = [
      'dependencies {',
      '    // AuCourant storage (Room). Added by plugins/with-aucourant-native.js.',
      `    implementation("androidx.room:room-runtime:${ROOM}")`,
      `    annotationProcessor("androidx.room:room-compiler:${ROOM}")`,
      '',
      '',
    ]
    cfg.modResults.contents = src.replace(anchor, lines.join('\n'))
    return cfg
  })

/** Hears about new SMS. `BROADCAST_SMS` is held only by the system, so no other app can send it fake ones. */
const withSmsReceiver = (config) =>
  withAndroidManifest(config, (cfg) => {
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults)
    const name = `${PKG}.SmsReceiver`
    app.receiver = (app.receiver ?? []).filter((r) => r.$['android:name'] !== name)
    app.receiver.push({
      $: { 'android:name': name, 'android:exported': 'true', 'android:permission': 'android.permission.BROADCAST_SMS' },
      'intent-filter': [{ action: [{ $: { 'android:name': 'android.provider.Telephony.SMS_RECEIVED' } }] }],
    })
    return cfg
  })

/** Fingerprint unlock (FingerprintModule.java). 1.1.0 is the newest stable release (checked 2026-11-22). */
const BIOMETRIC = '1.1.0'
const withBiometric = (config) =>
  withAppBuildGradle(config, (cfg) => {
    const src = cfg.modResults.contents
    if (src.includes('androidx.biometric:biometric')) return cfg
    const anchor = /^dependencies \{\r?\n/m
    if (!anchor.test(src)) throw new Error('[with-aucourant-native] Could not find the dependencies block in app/build.gradle.')
    const lines = ['dependencies {', '    // AuCourant fingerprint unlock. Added by plugins/with-aucourant-native.js.', `    implementation("androidx.biometric:biometric:${BIOMETRIC}")`, '', '']
    cfg.modResults.contents = src.replace(anchor, lines.join('\n'))
    return cfg
  })

module.exports = (config) => withBiometric(withSmsReceiver(withRoom(with64BitOnly(withFileProvider(withPackageRegistered(withJavaSources(config)))))))
